(187, 1, '2025-08-29 10:03:03', '2025-08-29 10:03:03', '/* General form styling */\n.tansche-form {\n    max-width: 600px;\n    margin: 30px auto;\n    padding: 25px;\n    background: #ff00ff;\n    border: 1px solid #ddd;\n    border-radius: 8px;\n    box-shadow: 0px 4px 10px rgba(0,0,0,0.05);\n}\n\n.tansche-form h2 {\n    text-align: center;\n    margin-bottom: 20px;\n    color: #2c3e50;\n}\n\n.tansche-form p {\n    margin: 15px 0;\n}\n\n.tansche-form input[type=\"text\"],\n.tansche-form input[type=\"date\"],\n.tansche-form input[type=\"file\"] {\n    width: 100%;\n    padding: 10px;\n    border: 1px solid #ccc;\n    border-radius: 6px;\n    font-size: 14px;\n}\n\n.tansche-form input[type=\"submit\"] {\n    display: block;\n    width: 100%;\n    padding: 12px;\n    background: #3498db;\n    border: none;\n    border-radius: 6px;\n    color: white;\n    font-size: 16px;\n    cursor: pointer;\n    transition: background 0.3s ease-in-out;\n}\n\n.tansche-form input[type=\"submit\"]:hover {\n    background: #2980b9;\n}\n\n/* Certificate download list */\n.tansche-cert-list {\n    max-width: 700px;\n    margin: 20px auto;\n    padding: 20px;\n    background: #f9f9f9;\n    border-radius: 8px;\n}\n\n.tansche-cert-list ul {\n    list-style: none;\n    padding: 0;\n}\n\n.tansche-cert-list li {\n    padding: 12px;\n    margin: 8px 0;\n    background: #fff;\n    border: 1px solid #eee;\n    border-radius: 6px;\n    display: flex;\n    justify-content: space-between;\n    align-items: center;\n}\n\n.tansche-cert-list li a {\n    background: #2ecc71;\n    color: white;\n    padding: 6px 12px;\n    border-radius: 4px;\n    text-decoration: none;\n    font-size: 13px;\n    transition: background 0.2s;\n}\n\n.tansche-cert-list li a:hover {\n    background: #27ae60;\n}\n\n/* Bulk button */\n.tansche-bulk {\n    display: block;\n    margin: 20px auto;\n    text-align: center;\n}\n\n.tansche-bulk a {\n    background: #e67e22;\n    padding: 10px 18px;\n    color: white;\n    border-radius: 6px;\n    text-decoration: none;\n    transition: background 0.2s;\n}\n\n.tansche-bulk a:hover {\n    background: #d35400;\n}\n', 'go', '', 'publish', 'closed', 'closed', '', 'go', '', '', '2025-08-30 05:21:51', '2025-08-30 05:21:51', '', 0, 'https://tnedunet.in/go/', 0, 'custom_css', '', 0),
